/* ================= Requirements library: list → regulation → requirement ================= */
const regReqs = r => r.sections.flatMap(s => s.reqs);
const regQs = r => regReqs(r).reduce((a, q) => a + (q.questions || []).length, 0);
const curReg = () => S.regs.find(r => r.id === S.ui.regId) || S.regs[0];
const findReq = ref => { for (const r of S.regs) for (const s of r.sections) for (const q of s.reqs) if (q.ref === ref) return { reg: r, sec: s, q }; return null; };
const orgsCovered = r => allTypes().filter(t => r.applies.includes(t.name)).reduce((a, t) => a + t.count, 0);
ACT.openReg = (id) => { S.ui.regId = id; S.ui.regTab = 'structure'; go('library/regulation'); };

screen('library', {
  t: 'Requirements library', layout: 'app', ws: 'regulator', crumbs: ['Requirements library'],
  render() {
    const f = ui('libF', { q: '', applies: 'All', st: 'All' });
    const rows = S.regs.filter(r => (f.applies === 'All' || r.applies.includes(f.applies)) && (f.st === 'All' || r.status === f.st) && (!f.q || (r.name + r.ref + r.category).toLowerCase().includes(f.q.toLowerCase())));
    return `${pageHead({ title: 'Requirements library', sub: 'The regulations you supervise against, broken into requirements, the questions organisations answer and the evidence they attach.', actions: btn('Import spreadsheet', { v: 'outline', i: 'table', act: 'reqImport' }) + btn('Add regulation', { v: 'secondary', i: 'plus', act: 'regNew', test: 'reg-new' }) + btn('Add with AI', { i: 'sparkle', go: 'library/ai', test: 'add-ai' }) })}
      ${S.ui.reqImported ? alertBox('ok', 'Spreadsheet imported', S.ui.reqImported, btn('Dismiss', { v: 'tertiary', size: 'sm', act: 'setUi', arg: 'reqImported=' })) : ''}
      <div class="card p0"><div class="tbl-tools"><form class="inp-wrap" data-form="libSearch" style="width:300px">${ic('magnifying-glass')}<input class="inp" id="lib-q" placeholder="Search regulations" value="${esc(f.q)}"></form>
        ${sel('lib-ap', [['All', 'Applies to: all categories'], ...typeOpts().map(t => [t, t])], f.applies, { attrs: 'data-change="libAp" style="width:250px"' })}<span class="grow"></span>
        <div class="seg sm">${['All', 'Published', 'Draft'].map(x => `<button class="${f.st === x ? 'on' : ''}" data-act="libSt" data-arg="${x}">${x}</button>`).join('')}</div></div>
        <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Regulation</th><th>Version</th><th>Effective</th><th class="num">Sections</th><th class="num">Requirements</th><th class="num">Questions</th><th>Applies to</th><th>Status</th><th></th></tr></thead><tbody>
        ${rows.map(r => `<tr class="click" data-act="openReg" data-arg="${r.id}" data-test="reg-${r.id}"><td><div class="row gap8">${tile('book-open-text', r.isNew ? 'ai' : '', 'sm')}<div><div class="strong">${esc(r.name)}</div><div class="cap muted">${esc(r.ref)} · ${esc(r.category)}</div></div></div></td><td class="small">${esc(r.version)}</td><td class="small">${esc(r.effective)}</td><td class="num tnum">${r.sections.length}</td><td class="num tnum">${regReqs(r).length}</td><td class="num tnum">${regQs(r)}</td><td class="small">${r.applies.length} categor${r.applies.length === 1 ? 'y' : 'ies'}</td><td>${statusChip(r.status)}${r.isNew ? ' ' + chip('AI drafted', 'ai', 'sparkle') : ''}</td><td>${ic('caret-right')}</td></tr>`).join('') || `<tr><td colspan="9">${empty('book-open-text', 'No regulations match', 'Change the filters, or add a regulation.')}</td></tr>`}
        </tbody></table></div><div class="tbl-foot">${rows.length} of ${S.regs.length} regulations</div></div>`;
  }
});
ACT.form_libSearch = () => { ui('libF').q = val('lib-q'); render(); };
ACT.chg_libAp = (v) => { ui('libF').applies = v; render(); };
ACT.libSt = (v) => { ui('libF').st = v; render(); };
ACT.regNew = () => openDialog(`${dlgHead('Add a regulation', 'Start with the basics. You add sections, requirements and questions next.', 'book-open-text')}<form class="col gap16" data-form="regNew" novalidate>${field('Name', inp('rn-name', '', { ph: 'e.g. Cloud Computing Guidelines 2026' }), { for: 'rn-name' })}<div class="grid g2" style="gap:12px">${field('Reference', inp('rn-ref', '', { ph: 'e.g. CCG' }), { for: 'rn-ref' })}${field('Category', inp('rn-cat', '', { ph: 'e.g. Cloud services' }), { for: 'rn-cat' })}${field('Version', inp('rn-ver', 'v1.0'), { for: 'rn-ver' })}${field('Effective date', inp('rn-eff', '2027-01-01', { type: 'date' }), { for: 'rn-eff' })}</div><div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Create regulation', { type: 'submit', test: 'reg-create' })}</div></form>`);
ACT.form_regNew = () => {
  const n = val('rn-name'), ref = (val('rn-ref') || '').toUpperCase(); if (!n || !ref) { toast('Add a name and a reference', 'bad'); return; }
  const id = uid('r'); S.regs.push({ id, ref, name: n, category: val('rn-cat') || 'General', version: val('rn-ver') || 'v1.0', effective: fmtDate(val('rn-eff') || '2027-01-01'), updated: 'Today', status: 'Draft', file: '', applies: [], desc: '', sections: [{ id: uid('s'), name: '1. General', reqs: [] }] });
  closeDialog(); addAudit('Created regulation', n); toast('Regulation created as a draft'); ACT.openReg(id);
};
ACT.reqImport = () => openDialog(`${dlgHead('Import requirements from a spreadsheet', 'One row per requirement: reference, title, text, questions, evidence, categories.', 'table')}<button class="drop" data-act="reqImportGo">${tile('cloud-arrow-up', '', 'lg')}<b>Drop your spreadsheet here</b><span class="cap muted">.xlsx or .csv</span></button><div class="row between">${btn('Download template', { v: 'tertiary', i: 'download-simple', act: 'savedToast', arg: 'Template downloaded' })}${btn('Cancel', { v: 'outline', act: 'closeDialog' })}</div>`);
ACT.reqImportGo = () => { closeDialog(); const r = S.regs.find(x => x.id === 'cpr'); if (!r.sections.some(s => s.name.startsWith('4.'))) r.sections.push({ id: 's4', name: '4. Disclosure', reqs: [{ ref: 'CPR-4.1', t: 'Publish fees and charges', text: 'Publish all fees and charges in plain language before a customer signs up.', guidance: '', weight: 'Normal (2)', evidence: ['Published tariff'], questions: [{ q: 'Are all fees published before sign-up?', choice: 'yn', comment: true, evidence: true, interview: false }] }] }); S.ui.reqImported = 'consumer-protection.xlsx: 12 rows read, 11 already in the library, 1 added to Consumer Protection Rules (CPR-4.1).'; addAudit('Imported requirements', 'consumer-protection.xlsx'); render(); toast('Requirements imported'); };

/* Regulation page — details panel left, structure / questions / evidence right (RegComply pattern) */
screen('library/regulation', {
  t: 'Regulation', layout: 'app', ws: 'regulator', crumbs: () => [['Requirements library', 'library'], curReg().name],
  render() {
    const r = curReg(); const tab = ui('regTab', 'structure'); const reqs = regReqs(r);
    const open = ui('secOpen_' + r.id, () => Object.fromEntries(r.sections.map((s, i) => [s.id, i < 2])));
    const det = [['Title', esc(r.name)], ['Reference', `<span class="mono">${esc(r.ref)}</span>`], ['Category', esc(r.category)], ['Status', statusChip(r.status)], ['Version', esc(r.version)], ['Effective from', esc(r.effective)], ['Total sections', r.sections.length], ['Total requirements', reqs.length], ['Total questions', regQs(r)], ['Organisations covered', orgsCovered(r)], ['Last updated', esc(r.updated || '—')]];
    let body = '';
    if (tab === 'structure') body = `<div class="tbl-tools"><div class="inp-wrap" style="width:280px">${ic('magnifying-glass')}<input class="inp" id="rs-q" placeholder="Search requirements" data-act-input="1"></div><span class="grow"></span>${btn('Expand all', { v: 'tertiary', size: 'sm', act: 'secAll', arg: r.id })}${btn('Add section', { v: 'outline', size: 'sm', i: 'plus', act: 'secAdd', arg: r.id })}</div>
      <div class="clause-tree">${r.sections.map(s => `<div class="cl-sec"><div class="cl-row sec" role="button" tabindex="0" data-act="secToggle" data-arg="${r.id}|${s.id}" aria-expanded="${!!open[s.id]}">${ic(open[s.id] ? 'caret-down' : 'caret-right')}<b class="grow">${esc(s.name)}</b><span class="cap muted">${s.reqs.length} requirement${s.reqs.length === 1 ? '' : 's'}</span><span class="acts">${btnIc('plus', 'reqAdd', r.id + '|' + s.id, 'Add requirement')}${btnIc('pencil-simple', 'secRename', r.id + '|' + s.id, 'Rename section')}</span></div>
        ${open[s.id] ? s.reqs.map(q => `<div class="cl-row req" data-act="openReq" data-arg="${q.ref}" data-test="req-${q.ref}"><span class="mono ref">${esc(q.ref)}</span><span class="grow strong">${esc(q.t)}</span><span class="cl-meta">${ic('question')}${(q.questions || []).length}</span><span class="cl-meta">${ic('paperclip')}${q.evidence.length}</span><span class="acts">${btnIc('eye', 'openReq', q.ref, 'View')}${btnIc('pencil-simple', 'editReq', q.ref, 'Edit')}</span></div>`).join('') + (s.reqs.length ? '' : `<div class="cl-row req muted small">No requirements yet. ${btn('Add requirement', { v: 'tertiary', size: 'sm', act: 'reqAdd', arg: r.id + '|' + s.id })}</div>`) : ''}</div>`).join('')}</div>`;
    if (tab === 'questions') {
      const sid = S.ui.qSec && r.sections.find(s => s.id === S.ui.qSec) ? S.ui.qSec : r.sections[0].id; const sec = r.sections.find(s => s.id === sid);
      let n = 0;
      body = `<div class="q-layout"><div class="q-secs"><div class="overline" style="padding:4px 8px 8px">Sections</div>${r.sections.map(s => `<button class="q-sec ${s.id === sid ? 'on' : ''}" data-act="qSec" data-arg="${s.id}"><span class="grow">${esc(s.name)}</span>${count(s.reqs.reduce((a, q) => a + (q.questions || []).length, 0))}</button>`).join('')}<button class="q-sec add" data-act="secAdd" data-arg="${r.id}">${ic('plus')}<span>Add a section</span></button></div>
        <div class="col gap12">${sec.reqs.map(q => (q.questions || []).map((qq, qi) => { n++; return `<div class="q-card"><div class="row top"><span class="q-n">${n}</span><div class="grow"><div class="strong">${esc(qq.q)}</div><div class="row wrap gap8" style="margin-top:6px">${qParts(qq)}<a href="#library/requirement" data-act="openReq" data-arg="${q.ref}" class="cap mono">${esc(q.ref)}</a></div></div>${btnIc('pencil-simple', 'editReq', q.ref, 'Edit')}</div></div>`; }).join('')).join('') || `<div class="card flat">${empty('question', 'No questions in this section', 'Add a requirement, then the questions organisations answer for it.')}</div>`}
          <div>${btn('Add question', { v: 'outline', size: 'sm', i: 'plus', act: 'qAdd', arg: r.id + '|' + sid, disabled: !sec.reqs.length })}</div></div></div>`;
    }
    if (tab === 'evidence') body = `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Evidence item</th><th>Requirement</th><th>Section</th></tr></thead><tbody>${r.sections.flatMap(s => s.reqs.flatMap(q => q.evidence.map(ev => `<tr class="click" data-act="openReq" data-arg="${q.ref}"><td><div class="row gap8">${ic('paperclip')}<span>${esc(ev)}</span></div></td><td><span class="mono small">${esc(q.ref)}</span> <span class="small muted">${esc(q.t)}</span></td><td class="small muted">${esc(s.name)}</td></tr>`))).join('') || `<tr><td colspan="3">${empty('paperclip', 'No evidence yet', 'Evidence items appear here as you add requirements.')}</td></tr>`}</tbody></table></div>`;
    if (tab === 'versions') body = `<div class="timeline" style="padding:20px">${[[r.version, r.updated || r.effective, 'Current version', true], ['v1.4', '1 Jun 2025', 'Wording changed in sections 4 and 7'], ['v1.0', '1 Jan 2024', 'First published']].slice(0, r.version === 'v1.0' ? 1 : 3).map(([v, d, n, cur]) => `<div class="tl">${tile('git-commit', cur ? 'brand' : '', 'sm')}<div class="grow"><div class="row gap8"><span class="tag mono">${v}</span><b>${n}</b></div><div class="cap muted">${d}</div></div></div>`).join('')}</div>`;
    return `<div class="reg-layout">
      <aside class="col gap16"><div class="card col gap12"><div class="h4">Details</div><dl class="det">${det.map(([k, v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>
          ${r.file ? fileRow(r.file, 'Source document · PDF', { i: 'file-pdf', actions: btnIc('download-simple', 'savedToast', 'Download started', 'Download') }) : ''}
          <div><div class="cap muted" style="margin-bottom:6px">Applies to</div><div class="row wrap gap6">${r.applies.map(a => tag(a)).join('') || '<span class="small muted">No categories yet</span>'}</div></div></div>
        <div class="card col gap4"><div class="h4" style="margin-bottom:6px">Actions</div>${[['pencil-simple', 'Edit details', 'regEdit'], ['plus', 'Add requirement', 'reqAdd'], ['copy', 'Create new version', 'regVersion'], [r.status === 'Draft' ? 'paper-plane-tilt' : 'archive', r.status === 'Draft' ? 'Publish regulation' : 'Archive regulation', r.status === 'Draft' ? 'regPublish' : 'regArchive']].map(([i, l, a]) => `<button class="menu-item" data-act="${a}" data-arg="${r.id}" data-test="${a}">${ic(i)}<span>${l}</span></button>`).join('')}</div></aside>
      <section class="col gap16" style="min-width:0"><div><div class="row wrap gap8"><span class="tag mono">${esc(r.ref)}</span>${statusChip(r.status)}</div><h1 class="h1" style="margin-top:6px">${esc(r.name)}</h1>${r.desc ? `<p class="muted" style="margin-top:4px;max-width:80ch">${esc(r.desc)}</p>` : ''}</div>
        <div class="card p0">${tabs([{ id: 'structure', label: 'Requirements', count: reqs.length }, { id: 'questions', label: 'Questions', count: regQs(r) }, { id: 'evidence', label: 'Evidence', count: reqs.reduce((a, q) => a + q.evidence.length, 0) }, { id: 'versions', label: 'Versions' }], tab, 'regTab')}${body}</div></section></div>`;
  },
  mount() { const q = $('#rs-q'); q && q.addEventListener('input', () => { const v = q.value.toLowerCase(); $$('.cl-row.req').forEach(r => { r.style.display = r.textContent.toLowerCase().includes(v) ? '' : 'none'; }); }); }
});
ACT.regTab = (t) => { S.ui.regTab = t; render(); };
ACT.secToggle = (arg) => { const [rid, sid] = arg.split('|'); const o = ui('secOpen_' + rid, {}); o[sid] = !o[sid]; render(); };
ACT.secAll = (rid) => { const r = S.regs.find(x => x.id === rid); S.ui['secOpen_' + rid] = Object.fromEntries(r.sections.map(s => [s.id, true])); render(); };
ACT.qSec = (id) => { S.ui.qSec = id; render(); };
ACT.secAdd = (rid) => openDialog(`${dlgHead('Add a section', 'Sections group related requirements, e.g. "5. Operations security".', 'list-numbers')}<form class="col gap16" data-form="secAdd" data-arg="${rid}">${field('Section name', inp('sec-name', (S.regs.find(x => x.id === rid).sections.length + 1) + '. '), { for: 'sec-name' })}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Add section', { type: 'submit' })}</div></form>`);
ACT.form_secAdd = (f) => { const r = S.regs.find(x => x.id === f.dataset.arg); const n = val('sec-name'); if (n.replace(/^\d+\.\s*/, '').length < 2) { toast('Name the section', 'bad'); return; } const s = { id: uid('s'), name: n, reqs: [] }; r.sections.push(s); ui('secOpen_' + r.id, {})[s.id] = true; closeDialog(); render(); toast('Section added'); };
ACT.secRename = (arg) => { const [rid, sid] = arg.split('|'); const s = S.regs.find(x => x.id === rid).sections.find(x => x.id === sid); openDialog(`${dlgHead('Rename section', '', 'pencil-simple')}<form class="col gap16" data-form="secRename" data-arg="${arg}">${field('Section name', inp('sec-ren', s.name), { for: 'sec-ren' })}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Save', { type: 'submit' })}</div></form>`); };
ACT.form_secRename = (f) => { const [rid, sid] = f.dataset.arg.split('|'); const s = S.regs.find(x => x.id === rid).sections.find(x => x.id === sid); s.name = val('sec-ren') || s.name; closeDialog(); render(); toast('Section renamed'); };
ACT.reqAdd = (arg) => { const [rid, sid] = String(arg).split('|'); const r = S.regs.find(x => x.id === rid); S.ui.newReq = { reg: rid, sec: sid || r.sections[r.sections.length - 1].id }; S.ui.editReq = '__new'; go('library/edit'); };
ACT.editReq = (ref) => { S.ui.editReq = ref; go('library/edit'); };
ACT.qAdd = (arg) => { const [rid, sid] = arg.split('|'); const sec = S.regs.find(x => x.id === rid).sections.find(x => x.id === sid); openDialog(`${dlgHead('Add a question', 'Organisations answer it as part of the requirement.', 'question')}<form class="col gap16" data-form="qAdd" data-arg="${arg}">${field('Requirement', sel('qa-req', sec.reqs.map(q => [q.ref, q.ref + ' · ' + q.t]), sec.reqs[0].ref), { for: 'qa-req' })}${field('Question', ta('qa-q', '', { ph: 'e.g. Who approved the current policy?', attrs: 'rows="2"' }), { for: 'qa-q' })}<div class="field"><label>Answer parts</label><div class="q-parts">${sel('qa-c', CHOICES, 'yn', { attrs: 'style="width:220px;height:32px"' })}${PARTS.map(([k, l, ico]) => `<label class="part-tog"><input type="checkbox" id="qa-${k}" ${k === 'interview' ? '' : 'checked'}>${ic(ico)}${l}</label>`).join('')}</div><div class="hint">Tick every part the organisation must give for this question.</div></div><div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Add question', { type: 'submit' })}</div></form>`); };
ACT.form_qAdd = () => { const q = findReq(val('qa-req')).q; const t = val('qa-q'); if (!t) { toast('Write the question', 'bad'); return; } (q.questions = q.questions || []).push({ q: t, choice: val('qa-c'), comment: val('qa-comment'), evidence: val('qa-evidence'), interview: val('qa-interview') }); closeDialog(); render(); toast('Question added'); };
ACT.regEdit = (rid) => { const r = S.regs.find(x => x.id === rid); openDialog(`${dlgHead('Edit details', esc(r.ref), 'pencil-simple')}<form class="col gap16" data-form="regEdit" data-arg="${rid}">${field('Name', inp('re-name', r.name), { for: 're-name' })}<div class="grid g2" style="gap:12px">${field('Category', inp('re-cat', r.category), { for: 're-cat' })}${field('Version', inp('re-ver', r.version), { for: 're-ver' })}</div>${field('Description', ta('re-desc', r.desc, { attrs: 'rows="3"' }), { for: 're-desc' })}<div class="field"><label>Applies to</label><div class="grid g2" style="gap:6px">${typeOpts().map((t, i) => ck('re-ap' + i, t, r.applies.includes(t), { attrs: `name="re-ap" value="${t}"` })).join('')}</div></div><div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Save', { type: 'submit' })}</div></form>`, { wide: true }); };
ACT.form_regEdit = (f) => { const r = S.regs.find(x => x.id === f.dataset.arg); Object.assign(r, { name: val('re-name') || r.name, category: val('re-cat'), version: val('re-ver'), desc: val('re-desc'), applies: $$('input[name=re-ap]:checked').map(x => x.value), updated: 'Today' }); closeDialog(); addAudit('Edited regulation', r.name); render(); toast('Details saved'); };
ACT.regVersion = (rid) => { const r = S.regs.find(x => x.id === rid); openDialog(`${dlgHead('Create a new version?', `A draft copy of ${esc(r.version)} is made. Programmes keep using ${esc(r.version)} until you publish the new one.`, 'copy')}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Create draft version', { act: 'regVersionGo', arg: rid })}</div>`); };
ACT.regVersionGo = (rid) => { const r = S.regs.find(x => x.id === rid); const m = r.version.match(/v(\d+)\.(\d+)/); r.version = m ? `v${m[1]}.${+m[2] + 1}` : r.version + '.1'; r.status = 'Draft'; r.updated = 'Today'; closeDialog(); addAudit('Created regulation version', r.name + ' ' + r.version); render(); toast(`${esc(r.version)} created as a draft`); };
ACT.regPublish = (rid) => { const r = S.regs.find(x => x.id === rid); if (!regReqs(r).length || !r.applies.length) { toast('Add at least one requirement and choose who it applies to before publishing', 'bad'); return; } r.status = 'Published'; r.updated = 'Today'; addAudit('Published regulation', r.name); render(); toast(`${esc(r.name)} published`); };
ACT.regArchive = (rid) => { const r = S.regs.find(x => x.id === rid); openDialog(`${dlgHead('Archive ' + esc(r.name) + '?', 'It stays readable for past programmes but cannot be used in new ones.', 'archive', 'warn')}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Archive', { v: 'danger', act: 'regArchiveGo', arg: rid })}</div>`); };
ACT.regArchiveGo = (rid) => { const r = S.regs.find(x => x.id === rid); r.status = 'Archived'; closeDialog(); addAudit('Archived regulation', r.name); render(); toast('Regulation archived'); };

/* Requirement page */
screen('library/requirement', {
  t: 'Requirement', layout: 'app', ws: 'regulator', crumbs: () => { const f = findReq(S.ui.reqRef) || findReq('ISR-4.1'); return [['Requirements library', 'library'], [f.reg.ref, 'library/regulation'], f.q.ref]; },
  render() {
    const f = findReq(S.ui.reqRef) || findReq('ISR-4.1'); const { reg, sec, q } = f; S.ui.regId = reg.id;
    const all = regReqs(reg); const i = all.indexOf(q); const prev = all[i - 1], next = all[i + 1];
    return `${pageHead({ over: `<a href="#library/regulation" data-go="library/regulation">${esc(reg.name)}</a> · ${esc(sec.name)}`, title: `<span class="mono ref-lg">${esc(q.ref)}</span> ${esc(q.t)}`, actions: btn('Previous', { v: 'outline', size: 'sm', i: 'caret-left', act: 'openReq', arg: prev ? prev.ref : '', disabled: !prev }) + btn('Next', { v: 'outline', size: 'sm', ir: 'caret-right', act: 'openReq', arg: next ? next.ref : '', disabled: !next }) + btn('Edit requirement', { i: 'pencil-simple', act: 'editReq', arg: q.ref, test: 'req-edit' }) })}
      <div class="grid side"><div class="col gap16">
        <div class="card col gap8"><div class="overline">Requirement</div><p style="font-size:15px;line-height:24px">${esc(q.text)}</p></div>
        <div class="card col gap12"><div class="row"><span class="h4 grow">Questions asked</span><span class="cap muted">${(q.questions || []).length} question${(q.questions || []).length === 1 ? '' : 's'}</span></div>${(q.questions || []).map((qq, n) => `<div class="q-line"><span class="q-n">${n + 1}</span><span class="grow">${esc(qq.q)}</span>${qParts(qq)}</div>`).join('') || '<p class="muted small">No questions yet.</p>'}<div>${btn('Suggest questions with AI', { v: 'tertiary', size: 'sm', i: 'sparkle', act: 'reqSuggest', arg: q.ref, test: 'req-suggest' })}</div><p class="cap muted">Organisations answer every question, then the assessor records an outcome using the programme's scoring scheme.</p></div>
        <div class="card col gap12"><div class="h4">Evidence required</div>${q.evidence.map(e => `<div class="ev-line">${tile('paperclip', '', 'sm')}<span class="grow">${esc(e)}</span>${chip('Required', 'info')}</div>`).join('') || '<p class="muted small">No evidence required.</p>'}</div>
        <div class="card col gap8"><div class="h4">Guidance for organisations</div><p class="muted">${esc(q.guidance || 'No guidance added yet.')}</p></div></div>
      <aside class="col gap16"><div class="card col gap12"><div class="h4">Details</div><dl class="det">${[['Reference', `<span class="mono">${esc(q.ref)}</span>`], ['Regulation', `<a href="#library/regulation" data-go="library/regulation">${esc(reg.ref)} ${esc(reg.version)}</a>`], ['Section', esc(sec.name)], ['Weight', esc(q.weight || 'Normal (2)')], ['Scoring scheme', esc(S.schemes.find(s => s.def).name)], ['Status', statusChip(reg.status)]].map(([k, v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></div>
        <div class="card col gap8"><div class="h4">Applies to</div><div class="row wrap gap6">${(q.applies || reg.applies).map(a => tag(a)).join('')}</div><p class="cap muted">${orgsCovered({ applies: q.applies || reg.applies })} organisations in these categories.</p></div></aside></div>`;
  }
});

/* Requirement editor (new or edit) */
screen('library/edit', {
  t: 'Edit requirement', layout: 'app', ws: 'regulator', crumbs: () => { const f = S.ui.editReq !== '__new' && findReq(S.ui.editReq); const r = f ? f.reg : (S.regs.find(x => x.id === (S.ui.newReq || {}).reg) || S.regs[0]); return [['Requirements library', 'library'], [r.ref, 'library/regulation'], f ? f.q.ref : 'New requirement']; },
  render() {
    const isNew = S.ui.editReq === '__new' || !findReq(S.ui.editReq || '');
    let reg, sec, q;
    if (isNew) { const nr = S.ui.newReq || { reg: S.regs[0].id }; reg = S.regs.find(x => x.id === nr.reg) || S.regs[0]; sec = reg.sections.find(s => s.id === nr.sec) || reg.sections[reg.sections.length - 1]; const n = regReqs(reg).filter(x => x.ref.startsWith(reg.ref + '-' + (parseInt(sec.name) || 1) + '.')).length + 1; q = { ref: `${reg.ref}-${parseInt(sec.name) || 1}.${n}`, t: '', text: '', evidence: [''], questions: [{ q: '', choice: 'yn', comment: true, evidence: true, interview: false }], guidance: '', weight: 'Normal (2)' }; }
    else ({ reg, sec, q } = findReq(S.ui.editReq));
    const key = isNew ? '__new' : q.ref;
    const ev = ui('evList_' + key, q.evidence.slice()); const qs = ui('qList_' + key, clone(q.questions || []));
    const applies = q.applies || reg.applies;
    return `${pageHead({ over: esc(reg.name) + ' · ' + esc(sec.name), title: isNew ? 'New requirement' : `<span class="mono ref-lg">${esc(q.ref)}</span> ${esc(q.t)}` })}
      <form class="grid side" data-form="req" data-arg="${key}" novalidate>
        <div class="col gap16"><div class="card col gap16"><div class="grid g2" style="gap:16px;grid-template-columns:160px minmax(0,1fr)">${field('Reference', inp('rq-ref', q.ref), { for: 'rq-ref' })}${field('Title', inp('rq-t', q.t, { ph: 'Short, plain title' }), { for: 'rq-t' })}</div>
          ${field('Requirement text', ta('rq-text', q.text, { ph: 'What the organisation must do', attrs: 'rows="3"' }), { for: 'rq-text' })}
          ${field('Guidance for organisations', ta('rq-g', q.guidance || '', { attrs: 'rows="2"', ph: 'How to answer and what good evidence looks like' }), { hint: 'Shown beside the requirement when organisations answer.', for: 'rq-g' })}</div>
          <div class="card col gap12" data-qkey="${key}"><div class="row between wrap"><div class="h4">Questions asked</div><div class="row gap4 wrap">${btn('Suggest with AI', { v: 'tertiary', size: 'sm', i: 'sparkle', act: 'edSuggest', arg: key, test: 'ed-suggest' })}${btn('Add question', { v: 'tertiary', size: 'sm', i: 'plus', act: 'qlAdd', arg: key })}</div></div>${qs.map((qq, i) => qEditRow(qq, i, 'data-ql')).join('') || '<p class="small muted">No questions yet.</p>'}</div>
          <div class="card col gap12"><div class="row between"><div class="h4">Evidence required</div>${btn('Add item', { v: 'tertiary', size: 'sm', i: 'plus', act: 'evAdd', arg: key })}</div>${ev.map((e, i) => `<div class="row">${ic('paperclip')}<input class="inp" data-ev="${i}" value="${esc(e)}" placeholder="e.g. Signed policy document">${btnIc('trash', 'evDel', key + '|' + i, 'Remove')}</div>`).join('')}</div></div>
        <div class="col gap16"><div class="card col gap12"><div class="h4">Applies to</div><div class="col gap8" style="max-height:260px;overflow:auto">${typeOpts().map((t, i) => ck('ap' + i, t, applies.includes(t), { attrs: `name="ap" value="${t}"` })).join('')}</div></div>
          <div class="card col gap16">${field('Weight', sel('rq-w', ['Low (1)', 'Normal (2)', 'High (3)'], q.weight || 'Normal (2)'), { for: 'rq-w' })}${field('Scoring scheme', `<input class="inp" value="${esc(S.schemes.find(s => s.def).name)}" readonly>`, { hint: 'Set by each programme. Default shown.' })}</div>
          <div class="row end">${btn('Cancel', { v: 'outline', act: 'reqCancel', arg: isNew ? '' : q.ref })}${btn(isNew ? 'Add requirement' : 'Save changes', { type: 'submit', test: 'req-save' })}</div></div></form>`;
  }
});
function readEd(key) { S.ui['evList_' + key] = $$('[data-ev]').map(x => x.value); S.ui['qList_' + key] = readQEdits('[data-ql]'); }
ACT.evAdd = (k) => { readEd(k); S.ui['evList_' + k].push(''); render(); };
ACT.evDel = (arg) => { const [k, i] = arg.split('|'); readEd(k); S.ui['evList_' + k].splice(+i, 1); render(); };
ACT.qlAdd = (k) => { readEd(k); S.ui['qList_' + k].push({ q: '', choice: 'yn', comment: true, evidence: false, interview: false }); render(); };
ACT.qeDel = (i, el) => { const host = el.closest('[data-qkey]'); if (host) { const k = host.dataset.qkey; readEd(k); S.ui['qList_' + k].splice(+i, 1); render(); } else if (ACT.psQDel) ACT.psQDel(i, el); };
ACT.edSuggest = (k) => { readEd(k); openSuggest({ ref: val('rq-ref'), t: val('rq-t') || 'this requirement' }, list => { S.ui['qList_' + k] = S.ui['qList_' + k].filter(x => x.q).concat(list); render(); toast(`${list.length} question${list.length > 1 ? 's' : ''} added. Edit them before saving.`, 'ok', 'sparkle'); }); };
ACT.reqSuggest = (ref) => { const f = findReq(ref); openSuggest(f.q, list => { f.q.questions = (f.q.questions || []).concat(list); f.reg.updated = 'Today'; addAudit('Added questions with AI', ref); render(); toast(`${list.length} question${list.length > 1 ? 's' : ''} added to ${esc(ref)}`, 'ok', 'sparkle'); }); };
ACT.reqCancel = (ref) => { ['evList_', 'qList_'].forEach(p => { S.ui[p + (ref || '__new')] = undefined; }); if (ref) { S.ui.reqRef = ref; go('library/requirement'); } else go('library/regulation'); };
ACT.form_req = (f) => {
  const key = f.dataset.arg; const t = val('rq-t'), text = val('rq-text'), ref = val('rq-ref');
  if (!t || !text) { toast('Add a title and the requirement text', 'bad'); return; }
  readEd(key);
  const data = { ref, t, text, guidance: val('rq-g'), weight: val('rq-w'), evidence: S.ui['evList_' + key].filter(Boolean), questions: S.ui['qList_' + key].filter(x => x.q), applies: $$('input[name=ap]:checked').map(x => x.value) };
  if (key === '__new') { const nr = S.ui.newReq || { reg: S.regs[0].id }; const reg = S.regs.find(x => x.id === nr.reg) || S.regs[0]; const sec = reg.sections.find(s => s.id === nr.sec) || reg.sections[reg.sections.length - 1]; sec.reqs.push(data); reg.updated = 'Today'; }
  else { const { q, reg } = findReq(key); Object.assign(q, data); reg.updated = 'Today'; }
  ['evList_', 'qList_'].forEach(p => { S.ui[p + key] = undefined; });
  addAudit(key === '__new' ? 'Added requirement' : 'Edited requirement', ref); toast(`${esc(ref)} saved`); S.ui.reqRef = ref; go('library/requirement');
};

/* B09 Add regulation with AI */
screen('library/ai', {
  t: 'Add regulation with AI', layout: 'app', ws: 'regulator', crumbs: [['Requirements library', 'library'], 'Add with AI'],
  render() {
    const st = ui('ai', { step: 0, items: clone(SEED.aiExtract), name: 'Cyber Resilience Regulation 2026' });
    const acc = st.items.filter(x => x.state === 'accepted').length, rej = st.items.filter(x => x.state === 'rejected').length, left = st.items.length - acc - rej;
    let body;
    if (st.step === 0) body = `<div class="grid side"><div class="card col gap16">${field('Regulation name', inp('ai-name', st.name), { for: 'ai-name' })}<div class="grid g2" style="gap:16px">${field('Version', inp('ai-ver', 'v1.0'), { for: 'ai-ver' })}${field('Effective date', inp('ai-eff', '2026-12-01', { type: 'date' }), { for: 'ai-eff' })}</div>
        <button class="drop" data-act="aiUpload" data-test="ai-upload" style="padding:40px">${tile('file-text', 'ai', 'lg')}<b>Upload the regulation as a PDF</b><span class="cap muted">Up to 200 pages. Demo: uses a sample 22-page PDF.</span></button></div>
      <div class="card col gap12">${tile('sparkle', 'ai', 'lg')}<div class="h4">How it works</div>${['AI reads the document and drafts one requirement per obligation', 'Each draft shows the page it came from and a confidence score', 'Your staff accept, edit or reject every draft. Nothing is published without a person'].map((t, i) => `<div class="row top small"><span class="av s24">${i + 1}</span><span>${t}</span></div>`).join('')}</div></div>`;
    else if (st.step === 1) body = `<div class="card col gap16" style="align-items:center;text-align:center;padding:56px">${tile('sparkle', 'ai', 'lg')}<div class="h3">Reading cyber-resilience-regulation.pdf</div><p class="muted small">22 pages · finding obligations and expected evidence</p><div style="width:min(420px,100%)">${bar(54, 'var(--ai-solid)')}</div></div>`;
    else body = `<div class="alert ai">${tile('sparkle', 'ai', 'sm')}<div class="grow"><div class="t">${st.items.length} requirements drafted from 22 pages</div><div class="b">Check each one against the source page. Low-confidence drafts are marked.</div></div><div class="row">${btn('Accept all above 85%', { v: 'secondary', size: 'sm', act: 'aiAcceptHigh', test: 'ai-accept-high' })}</div></div>
      <div class="row wrap gap8">${chip(acc + ' accepted', 'ok', 'check')}${chip(rej + ' rejected', 'neu', 'x')}${chip(left + ' to review', left ? 'info' : 'ok')}</div>
      <div class="col gap12">${st.items.map((x, i) => `<div class="card tight row top" style="${x.state === 'accepted' ? 'box-shadow:0 0 0 1.5px var(--ok-border),var(--e1)' : x.state === 'rejected' ? 'opacity:.6' : ''}"><span class="tag mono">${x.ref}</span><div class="grow col gap6">${S.ui.aiEdit === i ? `<input class="inp" id="ai-e-${i}" value="${esc(x.t)}">` : `<div class="strong">${esc(x.t)}</div>`}<div class="row wrap gap12 cap muted"><span>${ic('file-text')} Page ${x.page}</span><span class="conf">Confidence ${x.conf}% ${bar(x.conf, x.conf >= 85 ? 'var(--ok-icon)' : x.conf >= 70 ? 'var(--warn-icon)' : 'var(--bad-icon)')}</span></div>${x.warn ? `<div class="note" style="padding:8px 10px">${ic('warning')}<span>${esc(x.warn)}</span></div>` : ''}</div>
        <div class="row gap4">${x.state === 'accepted' ? chip('Accepted', 'ok', 'check') + btnIc('arrow-u-up-left', 'aiSet', i + '|', 'Undo') : x.state === 'rejected' ? chip('Rejected', 'neu') + btnIc('arrow-u-up-left', 'aiSet', i + '|', 'Undo') : S.ui.aiEdit === i ? btn('Save', { size: 'sm', act: 'aiSaveEdit', arg: i }) : btn('Reject', { v: 'tertiary', size: 'sm', act: 'aiSet', arg: i + '|rejected' }) + btn('Edit', { v: 'outline', size: 'sm', act: 'aiEdit', arg: i }) + btn('Accept', { v: 'secondary', size: 'sm', act: 'aiSet', arg: i + '|accepted', test: 'ai-acc-' + i })}</div></div>`).join('')}</div>
      <div class="row end">${btn('Cancel', { v: 'outline', go: 'library' })}${btn(`Add ${acc} requirements to the library`, { act: 'aiPublish', disabled: !acc || left > 0, test: 'ai-publish' })}</div>${left ? `<p class="cap muted" style="text-align:right">Review every draft to continue. ${left} left.</p>` : ''}`;
    return `${pageHead({ title: 'Add a regulation with AI', sub: 'Upload the regulation. AI drafts the requirements; your team decides what goes in.' })}${stepper(['Upload', 'Read', 'Review drafts'], Math.min(st.step, 2))}${body}`;
  }
});
ACT.aiUpload = () => { const st = ui('ai'); st.name = val('ai-name') || st.name; st.step = 1; render(); setTimeout(() => { if (S.route === 'library/ai' && ui('ai').step === 1) { st.step = 2; render(); } }, 1400); };
ACT.aiSet = (arg) => { const [i, v] = arg.split('|'); ui('ai').items[+i].state = v; render(); };
ACT.aiEdit = (i) => { S.ui.aiEdit = +i; render(); };
ACT.aiSaveEdit = (i) => { const st = ui('ai'); st.items[+i].t = val('ai-e-' + i) || st.items[+i].t; st.items[+i].state = 'accepted'; st.items[+i].warn = null; S.ui.aiEdit = null; render(); toast('Draft edited and accepted'); };
ACT.aiAcceptHigh = () => { ui('ai').items.forEach(x => { if (x.conf >= 85 && !x.state) x.state = 'accepted'; }); render(); };
ACT.aiPublish = () => {
  const st = ui('ai'); const acc = st.items.filter(x => x.state === 'accepted');
  S.regs.unshift({ id: 'crr', ref: 'CRR', name: st.name, category: 'Cyber resilience', version: 'v1.0', effective: '1 Dec 2026', updated: 'Today', status: 'Draft', isNew: true, file: 'cyber-resilience-regulation.pdf', desc: 'Drafted with AI from the uploaded PDF and reviewed by your team. Check questions and evidence, then publish.', applies: ['Commercial bank', 'Microfinance bank', 'Payment solution service provider'], sections: [{ id: 'ai1', name: '1. Drafted requirements', reqs: acc.map(x => ({ ref: x.ref, t: x.t, text: x.t + '.', guidance: '', weight: 'Normal (2)', evidence: ['Evidence to be confirmed'], questions: [{ q: 'Does the organisation meet this requirement?', choice: 'yn', comment: true, evidence: true, interview: false }] })) }] });
  addAudit('Added regulation with AI', `${st.name} · ${acc.length} requirements`);
  S.ui.ai = undefined; S.ui.regId = 'crr'; S.ui.regTab = 'structure'; toast(`${acc.length} requirements added as a draft regulation`, 'ok', 'sparkle'); go('library/regulation');
};

/* B10 Scoring schemes */
screen('settings/scoring', {
  t: 'Scoring schemes', layout: 'app', ws: 'regulator', crumbs: [['Settings', 'settings/categories'], 'Scoring schemes'],
  render() {
    const cur = ui('schSel', 'four'); const s = S.schemes.find(x => x.id === cur) || S.schemes[0];
    return `${settingsHead('settings/scoring')}<div class="row wrap"><p class="muted small grow">The assessor chooses an outcome for each requirement. The scheme turns outcomes into scores and rating bands. Scores use the assessor outcome only, never the organisation's own answer. Programmes pick a scheme; the default is used otherwise.</p>${btn('New scheme', { size: 'sm', i: 'plus', act: 'schNew' })}</div>
      <div class="grid side-l">
        <div class="col gap8">${S.schemes.map(x => `<button class="choice ${x.id === cur ? 'on' : ''}" data-act="schSel" data-arg="${x.id}" data-test="sch-${x.id}"><span class="grow"><b>${esc(x.name)}</b><br><span class="cap muted">${esc(x.kind)} · used in ${x.used} programme${x.used === 1 ? '' : 's'}</span></span>${x.def ? chip('Default', 'brand', 'star') : ''}</button>`).join('')}</div>
        <div class="col gap24"><div class="card col gap16"><div class="row"><div class="grow"><div class="overline">${esc(s.kind)}</div><div class="h3">${esc(s.name)}</div></div>${s.def ? chip('Default for new programmes', 'brand', 'star') : btn('Make default', { v: 'secondary', size: 'sm', act: 'schDefault', arg: s.id })}</div>
          <div class="tbl-wrap" style="border:1px solid var(--border);border-radius:12px"><table class="tbl"><thead><tr><th>Outcome</th><th>Points</th><th>Meaning</th></tr></thead><tbody>${s.levels.map(([n, p, t]) => `<tr><td>${chip(n, t)}</td><td class="tnum">${p === null ? '<span class="muted">Not scored</span>' : p}</td><td class="small muted">${p === null ? 'Left out of the score; the requirement does not apply' : p === 100 ? 'Fully meets the requirement' : p === 0 ? 'Does not meet the requirement' : 'Meets part of the requirement'}</td></tr>`).join('')}</tbody></table></div></div>
          <div class="card col gap16"><div class="row"><div class="h4 grow">Rating bands</div>${btn('Edit bands', { v: 'tertiary', size: 'sm', i: 'pencil-simple', act: 'bandEdit', arg: s.id })}</div><p class="small muted">The overall score (0 to 100) is the weighted average of scored requirements.</p>
            <div style="display:flex;height:36px;border-radius:10px;overflow:hidden">${s.bands.map(([n, min], i) => { const max = i === 0 ? 100 : s.bands[i - 1][1]; const w = Math.max(max - min, 8); const col = ['var(--ok-solid)', '#3f9b62', 'var(--warn-icon)', 'var(--bad-icon)'][i] || 'var(--neu-icon)'; return `<div style="flex:${w};background:${col};color:#fff;display:grid;place-items:center;font-size:12px;font-weight:600">${n}</div>`; }).join('')}</div>
            <div class="grid g4" style="gap:8px">${s.bands.map(([n, min], i) => `<div class="small"><b>${n}</b><br><span class="muted tnum">${i === 0 ? min + ' to 100' : min + ' to ' + (s.bands[i - 1][1] - 1)}</span></div>`).join('')}</div></div>
</div></div>`;
  }
});
ACT.schSel = (id) => { S.ui.schSel = id; render(); };
ACT.bandEdit = (id) => { const s = S.schemes.find(x => x.id === id); openDialog(`${dlgHead('Edit rating bands', 'Set the lowest score for each band. The top band runs to 100.', 'target')}<div class="col gap12">${s.bands.map(([n, m], i) => `<div class="row"><input class="inp" id="bn${i}" value="${esc(n)}" style="flex:1"><span class="muted small">from</span><input class="inp" id="bm${i}" type="number" min="0" max="100" value="${m}" style="width:90px" ${i === s.bands.length - 1 ? 'readonly' : ''}></div>`).join('')}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Save bands', { act: 'bandSave', arg: id })}</div></div>`); };
ACT.bandSave = (id) => { const s = S.schemes.find(x => x.id === id); const nb = s.bands.map((b, i) => [val('bn' + i) || b[0], +val('bm' + i)]); for (let i = 1; i < nb.length; i++) if (nb[i][1] >= nb[i - 1][1]) { toast('Each band must start lower than the one above it', 'bad'); return; } s.bands = nb; closeDialog(); render(); toast('Rating bands saved'); };
ACT.schDefault = (id) => { S.schemes.forEach(s => s.def = s.id === id); render(); toast('Default scheme changed'); };
ACT.schNew = () => openDialog(`${dlgHead('New scoring scheme', 'Start from a template, then adjust levels and bands.', 'target')}<div class="col gap8">${S.schemes.map(s => `<button class="choice" data-act="schCopy" data-arg="${s.id}"><span class="grow"><b>Copy ${esc(s.name)}</b><br><span class="cap muted">${s.levels.length} levels</span></span>${ic('caret-right')}</button>`).join('')}</div>`);
ACT.schCopy = (id) => { const s = clone(S.schemes.find(x => x.id === id)); s.id = uid('sc'); s.name = s.name + ' (copy)'; s.def = false; s.used = 0; S.schemes.push(s); S.ui.schSel = s.id; closeDialog(); render(); toast('Scheme created'); };

/* B11 Assurance firm types */
screen('settings/firm-types', {
  t: 'Firm types', layout: 'app', ws: 'regulator', crumbs: [['Settings', 'settings/categories'], 'Firm types'],
  render() {
    const r = S.firmRules;
    return `${settingsHead('settings/firm-types')}<p class="muted small">Firms apply for accreditation by type. Set what each type must show, and how long accreditation lasts.</p>
      <div class="grid g2">${S.firmTypes.map((t, i) => `<div class="card col gap12"><div class="row">${tile(t.icon)}<div class="grow h4">${esc(t.name)}</div>${chip(Object.values(S.firms).filter(f => f.types.some(x => x.startsWith(t.name.split(' ')[0]))).length + ' firms', 'neu')}</div>
        <div class="overline">Accreditation criteria</div><ul style="margin:0;padding-left:18px;display:flex;flex-direction:column;gap:4px" class="small">${t.criteria.map(c => `<li>${esc(c)}</li>`).join('')}</ul>
        ${kv([['Assessor credentials', esc(t.creds)], ['Documents', esc(t.docs)]])}
        <div class="row end">${btn('Edit criteria', { v: 'tertiary', size: 'sm', i: 'pencil-simple', act: 'ftEdit', arg: i })}</div></div>`).join('')}</div>
      <form class="card col gap16" data-form="firmRules"><div class="h4">Rules for every type</div><div class="grid g3" style="gap:16px">${field('Accreditation lasts', `<div class="row gap8">${inp('fr-ren', r.renewal, { type: 'number', attrs: 'min="1" style="width:100px"' })}<span class="muted">months</span></div>`, { for: 'fr-ren' })}${field('Renewal reminder', `<div class="row gap8">${inp('fr-grace', r.grace, { type: 'number', attrs: 'style="width:100px"' })}<span class="muted">days before expiry</span></div>`, { for: 'fr-grace' })}${field('Independence window', `<div class="row gap8">${inp('fr-coi', r.conflictMonths, { type: 'number', attrs: 'style="width:100px"' })}<span class="muted">months</span></div>`, { hint: 'A firm cannot assess an organisation it advised in this period.', for: 'fr-coi' })}</div>
        ${note('Organisations may ask to use a firm that is not accredited. You approve or decline each request (Drop B).')}<div class="row end">${btn('Save firm types', { type: 'submit', test: 'save-ft' })}</div></form>`;
  }
});
ACT.ftEdit = (i) => { const t = S.firmTypes[+i]; openDialog(`${dlgHead('Edit ' + esc(t.name), 'One criterion per line.', 'pencil-simple')}<div class="col gap16">${field('Criteria', ta('ft-c', t.criteria.join('\n'), { attrs: 'rows="5"' }), { for: 'ft-c' })}${field('Assessor credentials', inp('ft-cr', t.creds), { for: 'ft-cr' })}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Save', { act: 'ftSave', arg: i })}</div></div>`, { wide: true }); };
ACT.ftSave = (i) => { const t = S.firmTypes[+i]; t.criteria = val('ft-c').split('\n').map(x => x.trim()).filter(Boolean); t.creds = val('ft-cr'); closeDialog(); render(); toast('Criteria updated'); };
ACT.form_firmRules = () => { Object.assign(S.firmRules, { renewal: val('fr-ren'), grace: val('fr-grace'), conflictMonths: val('fr-coi') }); toast('Firm types saved'); render(); };

/* B12 Deadlines & reminders */
screen('settings/deadlines', {
  t: 'Deadlines and reminders', layout: 'app', ws: 'regulator', crumbs: [['Settings', 'settings/categories'], 'Deadlines & reminders'],
  render() {
    const d = S.deadlines;
    return `${settingsHead('settings/deadlines')}<p class="muted small">Defaults for new programmes and returns. Each programme can change them.</p>
      <form class="grid side" data-form="deadlines">
        <div class="col gap24"><div class="card col gap16"><div class="h4">Responses and returns</div><div class="grid g2" style="gap:16px">${field('Default response window', `<div class="row gap8">${inp('dl-win', d.window, { type: 'number', attrs: 'style="width:110px"' })}<span class="muted">days</span></div>`, { for: 'dl-win' })}${field('Grace period for returns', `<div class="row gap8">${inp('dl-grace', d.returnsGrace, { type: 'number', attrs: 'style="width:110px"' })}<span class="muted">days, then marked late</span></div>`, { for: 'dl-grace' })}</div>
          ${field('Send reminders', inp('dl-rem', d.reminders), { hint: 'Days before the due date, separated by commas.', for: 'dl-rem' })}
          ${field('Escalate overdue work to the supervisor after', `<div class="row gap8">${inp('dl-esc', d.escalate, { type: 'number', attrs: 'style="width:110px"' })}<span class="muted">days overdue</span></div>`, { for: 'dl-esc' })}</div>
          <div class="card col gap16"><div class="h4">Invitations and digests</div><div class="grid g2" style="gap:16px">${field('Invitations expire after', `<div class="row gap8">${inp('dl-inv', d.inviteExpiry, { type: 'number', attrs: 'style="width:110px"' })}<span class="muted">days</span></div>`, { for: 'dl-inv' })}${field('Supervisor digest', sel('dl-dig', ['Off', 'Daily at 08:00', 'Weekly on Monday'], d.digest), { for: 'dl-dig' })}</div>${field('Time zone', sel('dl-tz', ['West Africa Time (WAT, UTC+1)', 'GMT (UTC+0)', 'East Africa Time (UTC+3)'], d.tz), { for: 'dl-tz' })}</div>
          <div class="row end">${btn('Save deadlines', { type: 'submit', test: 'save-deadlines' })}</div></div>
        <div class="card col gap12"><div class="h4">Example</div><p class="small muted">A response due on 30 November:</p><div class="timeline">${d.reminders.split(',').map(x => x.trim()).filter(Boolean).map(n => `<div class="tl">${tile('bell', 'info', 'sm')}<div class="small"><b>Reminder</b><br><span class="muted">${n} day${n === '1' ? '' : 's'} before</span></div></div>`).join('')}<div class="tl">${tile('flag', 'warn', 'sm')}<div class="small"><b>Due</b><br><span class="muted">30 Nov</span></div></div><div class="tl">${tile('warning', 'bad', 'sm')}<div class="small"><b>Escalated to supervisor</b><br><span class="muted">${d.escalate} days overdue</span></div></div></div></div>
      </form>`;
  }
});
ACT.form_deadlines = () => { Object.assign(S.deadlines, { window: val('dl-win'), returnsGrace: val('dl-grace'), reminders: val('dl-rem'), escalate: val('dl-esc'), inviteExpiry: val('dl-inv'), digest: val('dl-dig'), tz: val('dl-tz') }); toast('Deadlines and reminders saved'); render(); };

